/**
 * ═══════════════════════════════════════════════════════════════════════
 *  فایل کامل دسته‌بندی‌های باسلام (Basalam.com)
 * ──────────────────────────────────────────────────────────────────────
 *  منبع داده (API رسمی):
 *      GET https://services.basalam.com/web/v1/navigation/navigation/tree
 *
 *  تاریخ استخراج : 2026-11-04  (۱۴۰۵/۰۸/۱۳ شمسی)
 *  تعداد کل      : 1116 دسته‌بندی
 *                  ├─ سطح 1 (دسته‌های والد اصلی): 14 مورد
 *                  ├─ سطح 2 (زیر‌دسته‌ها (فرزند والد)): 119 مورد
 *                  ├─ سطح 3 (زیر‌دسته‌های سطح سه): 983 مورد
 *
 *  ساختار هر گره (node):
 *      [id]        شناسه عددی دسته در باسلام
 *      [title]     عنوان فارسی دسته
 *      [slug]      نامک (استفاده در آدرس basalam.com/cat/{slug})
 *      [image]     آدرس تصویر دسته (svg/png از statics.basalam.com)
 *      [level]     سطح دسته (۱ = والد اصلی، ۲ و ۳ = فرزند)
 *      [parent_id] شناسه والد (۰ = دسته والد اصلی/ریشه)
 *      [rank]      ترتیب نمایش در باسلام
 *      [children]  آرایه فرزندان (سلسله‌مراتب والد/فرزند حفظ شده است)
 *
 *  توابع موجود در این فایل:
 *      basalam_categories()              → آرایه کامل درختی (والد ← فرزند)
 *      basalam_flat_categories()         → لیست تخت همه دسته‌ها + مسیر کامل
 *      basalam_find_category($id)        → جستجوی دسته با شناسه
 *      basalam_category_image($cat)      → تصویر دسته (با fallback به تصویر والد)
 *      basalam_fetch_categories()        → دریافت زنده از API باسلام (اختیاری)
 *      basalam_render_categories_html()  → خروجی HTML آماده (لیست با تصویر)
 *
 *  نمونه استفاده:
 *      $cats = basalam_categories();
 *      foreach ($cats as $parent) {
 *          echo $parent['title'] . " => " . $parent['image'] . PHP_EOL;
 *          foreach ($parent['children'] as $child) {
 *              echo "  └─ " . $child['title'] . PHP_EOL;
 *          }
 *      }
 *
 *  اجرای مستقیم در ترمینال (نمایش کل درخت):
 *      php basalam-categories.php
 *      php basalam-categories.php --flat   ← لیست تخت
 *      php basalam-categories.php --json   ← خروجی JSON
 *
 *  نکته: دسته‌های «چرخ خیاطی دینام سرخود» و «تبلت سامسونگ» در خودِ API
 *  باسلام تصویر خالی دارند؛ تابع basalam_category_image() به‌طور خودکار
 *  از تصویر دسته والد استفاده می‌کند.
 * ═══════════════════════════════════════════════════════════════════════
 */
