if (! function_exists('basalam_flat_categories')) {
    /**
     * لیست تخت همه دسته‌ها (مناسب برای <select> و جستجو).
     * هر عنصر شامل «path» (مسیر کامل از والد تا فرزند) هم هست.
     *
     * @return array<int, array>
     */
    function basalam_flat_categories(): array
    {
        $flat = [];

        $walk = function (array $items, array $trail) use (&$walk, &$flat) {
            foreach ($items as $cat) {
                $pathTitles = array_merge($trail, [$cat['title']]);
                $flat[] = [
                    'id' => $cat['id'],
                    'title' => $cat['title'],
                    'slug' => $cat['slug'],
                    'image' => $cat['image'],
                    'level' => $cat['level'],
                    'parent_id' => $cat['parent_id'],
                    'path' => implode(' > ', $pathTitles),
                    'url' => 'https://basalam.com/cat/'.rawurlencode($cat['slug']),
                ];
                $walk($cat['children'], $pathTitles);
            }
        };

        $walk(basalam_categories(), []);

        return $flat;
    }
}

if (! function_exists('basalam_find_category')) {
    /**
     * یافتن دسته بر اساس شناسه (خروجی شامل فرزندان دسته نیز هست).
     *
     * @param  int  $id  شناسه دسته
     * @return array|null آرایه دسته یا null در صورت نبود
     */
    function basalam_find_category(int $id): ?array
    {
        $search = function (array $items) use ($id, &$search) {
            foreach ($items as $cat) {
                if ($cat['id'] === $id) {
                    return $cat;
                }
                $found = $search($cat['children']);
                if ($found !== null) {
                    return $found;
                }
            }

            return null;
        };

        return $search(basalam_categories());
    }
}

if (! function_exists('basalam_category_image')) {
    /**
     * تصویر دسته؛ اگر دسته تصویر نداشته باشد تصویر والدش برگردانده می‌شود.
     *
     * @param  array  $cat  آرایه دسته
     * @param  bool  $fallback  استفاده از تصویر والد در نبود تصویر
     * @return string آدرس تصویر (می‌تواند رشته خالی باشد)
     */
    function basalam_category_image(array $cat, bool $fallback = true): string
    {
        if ($cat['image'] !== '' || ! $fallback) {
            return $cat['image'];
        }

        $parent = $cat['parent_id'] > 0 ? basalam_find_category((int) $cat['parent_id']) : null;

        return $parent['image'] ?? '';
    }
}

if (! function_exists('basalam_fetch_categories')) {
    /**
     * (اختیاری) دریافت نسخه زنده دسته‌بندی‌ها از API باسلام.
     * اگر فراخوانی API ناموفق بود، همان داده ثابت این فایل برگردانده می‌شود.
     *
     * @param  int  $timeout  مهلای درخواست به ثانیه
     * @return array درخت دسته‌بندی‌ها
     */
    function basalam_fetch_categories(int $timeout = 10): array
    {
        $url = 'https://services.basalam.com/web/v1/navigation/navigation/tree';

        $context = stream_context_create([
            'http' => [
                'method' => 'GET',
                'timeout' => $timeout,
                'header' => "Accept: application/json\r\n"
                    ."User-Agent: basalam-categories-php/1.0\r\n",
                'ignore_errors' => true,
            ],
        ]);

        $raw = @file_get_contents($url, false, $context);
        if ($raw === false) {
            return basalam_categories(); // fallback به داده ثابت
        }

        $decoded = json_decode($raw, true);
        if (! is_array($decoded) || empty($decoded['data']) || ! is_array($decoded['data'])) {
            return basalam_categories(); // fallback به داده ثابت
        }

        $normalize = function (array $items) use (&$normalize) {
            $out = [];
            foreach ($items as $item) {
                $out[] = [
                    'id' => (int) ($item['id'] ?? 0),
                    'title' => trim((string) ($item['title'] ?? '')),
                    'slug' => trim((string) ($item['slug'] ?? '')),
                    'image' => trim((string) ($item['image_url'] ?? '')),
                    'level' => (int) ($item['level'] ?? 0),
                    'parent_id' => (int) ($item['parent_id'] ?? 0),
                    'rank' => (int) ($item['rank'] ?? 0),
                    'children' => $normalize(is_array($item['children'] ?? null) ? $item['children'] : []),
                ];
            }

            return $out;
        };

        return $normalize($decoded['data']);
    }
}

if (! function_exists('basalam_render_categories_html')) {
    /**
     * خروجی HTML آماده: لیست درختی دسته‌ها همراه با تصویر هر دسته.
     *
     * @param  array|null  $cats  درخت دسته‌ها (پیش‌فرض: basalam_categories())
     * @return string کد HTML
     */
    function basalam_render_categories_html(?array $cats = null): string
    {
        $cats = $cats ?? basalam_categories();

        $render = function (array $items) use (&$render) {
            $html = '<ul class="basalam-categories">';
            foreach ($items as $cat) {
                $img = basalam_category_image($cat);
                $url = 'https://basalam.com/cat/'.rawurlencode($cat['slug']);
                $title = htmlspecialchars($cat['title'], ENT_QUOTES, 'UTF-8');
                $html .= '<li class="basalam-category basalam-level-'.(int) $cat['level'].'">';
                if ($img !== '') {
                    $html .= '<img src="'.htmlspecialchars($img, ENT_QUOTES, 'UTF-8').'" alt="'.$title.'" width="32" height="32" loading="lazy">';
                }
                $html .= '<a href="'.$url.'" target="_blank" rel="noopener">'.$title.'</a>';
                if (! empty($cat['children'])) {
                    $html .= $render($cat['children']);
                }
                $html .= '</li>';
            }

            return $html.'</ul>';
        };

        return $render($cats);
    }
}

/* ───────────── اجرای مستقیم از خط فرمان (php basalam-categories.php) ───────────── */
if (PHP_SAPI === 'cli' && isset($argv[0]) && realpath($argv[0]) === realpath(__FILE__)) {
    $flag = $argv[1] ?? '';

    if ($flag === '--json') {
        echo json_encode(basalam_categories(), JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT), PHP_EOL;
        exit(0);
    }

    if ($flag === '--flat') {
        printf("%-8s %-8s %-6s %s\n", 'id', 'parent', 'lvl', 'title (path) | image');
        foreach (basalam_flat_categories() as $c) {
            printf("%-8d %-8d %-6d %s | %s\n", $c['id'], $c['parent_id'], $c['level'], $c['path'], $c['image']);
        }
        exit(0);
    }

    $all = basalam_categories();
    $total = count(basalam_flat_categories());
    echo '════════ دسته‌بندی‌های باسلام ('.$total.' دسته) ════════'.PHP_EOL.PHP_EOL;
    $printTree = function (array $items, string $prefix) use (&$printTree) {
        $last = count($items);
        $i = 0;
        foreach ($items as $cat) {
            $i++;
            $branch = $i === $last ? '└─ ' : '├─ ';
            $img = basalam_category_image($cat);
            echo $prefix.$branch.$cat['title'].'  [id='.$cat['id'].']'.PHP_EOL;
            echo $prefix.($i === $last ? '   ' : '│  ').'    🖼  '.$img.PHP_EOL;
            $printTree($cat['children'], $prefix.($i === $last ? '   ' : '│  '));
        }
    };
    foreach ($all as $parent) {
        $img = basalam_category_image($parent);
        echo '▶ '.$parent['title'].'  [id='.$parent['id'].']'.PHP_EOL;
        echo '     🖼  '.$img.PHP_EOL;
        $printTree($parent['children'], '  ');
        echo PHP_EOL;
    }
    exit(0);
}

/* در صورت include کردن فایل، خودِ آرایه برگردانده می‌شود: */
return basalam_categories();
